import React, { useState, useEffect, useCallback, useRef } from 'react';
import { createClient } from '@supabase/supabase-js';

// ─── SUPABASE ─────────────────────────────────────────────────────────────────
const SUPABASE_URL = 'https://qvibdnrfywisvfsqgqux.supabase.co';
const SUPABASE_ANON =
  'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InF2aWJkbnJmeXdpc3Zmc3FncXV4Iiwicm9sZSI6ImFub24iLCJpYXQiOjE3Nzg4OTE5MTcsImV4cCI6MjA5NDQ2NzkxN30.qPNjcpQpHPV5_SVz3U-JC18CcZ6vxio9vImA3CKg5jk';
const sb = createClient(SUPABASE_URL, SUPABASE_ANON);

// ─── PERIOD KEYS (server-side reset logic via keys, not deletes) ──────────────
const dailyKey = () =>
  new Date().toLocaleDateString('sv-SE', { timeZone: 'Europe/Malta' });
const weeklyKey = () => {
  const now = new Date(
    new Date().toLocaleString('en-US', { timeZone: 'Europe/Malta' })
  );
  const day = now.getDay();
  const diff = now.getDate() - day + (day === 0 ? -6 : 1);
  return new Date(now.setDate(diff)).toLocaleDateString('sv-SE');
};
const monthlyKey = () =>
  new Date()
    .toLocaleDateString('sv-SE', { timeZone: 'Europe/Malta' })
    .slice(0, 7);

// ─── STATIC DATA ─────────────────────────────────────────────────────────────
const ROOMS = [
  { id: 'ensuite', label: 'Ensuite' },
  { id: 'main_bath', label: 'Main Bathroom' },
  { id: 'main_bed', label: 'Main Bedroom' },
  { id: 'girls_bed', label: "Girls' Bedroom" },
  { id: 'finn', label: "Finn's Room" },
  { id: 'open', label: 'Open Plan Kitchen/Living/Dining' },
];

const PLANNING_EVENTS_INIT = [
  {
    id: 'pl1',
    text: "Plan Father's Day",
    date: '31/05/2026',
    trigger_month: '05/2026',
    notes: '',
    recurring: true,
  },
  {
    id: 'pl2',
