function Checkbox({ checked, onChange, color = 'var(--chores)', size = 22 }) {
  const [anim, setAnim] = useState(false);
  return (
    <button
      onClick={() => {
        setAnim(true);
        setTimeout(() => setAnim(false), 300);
        onChange();
      }}
      className={anim ? 'pop' : ''}
      style={{
        width: size,
        height: size,
        borderRadius: size * 0.3,
        border: `1.5px solid ${checked ? color : 'var(--border)'}`,
        background: checked ? color : 'transparent',
        flexShrink: 0,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        transition: 'all 0.18s',
        outline: 'none',
        boxShadow: checked ? `0 2px 8px ${color}44` : 'none',
      }}
    >
      {checked && (
        <svg width={size * 0.5} height={size * 0.5} viewBox="0 0 12 12">
          <polyline
            points="2,6 5,9 10,3"
            fill="none"
            stroke="#fff"
            strokeWidth="2.2"
            strokeLinecap="round"
            strokeLinejoin="round"
          />
        </svg>
      )}
    </button>
  );
}

function Bar({ done, total, color }) {
  const pct = total ? (done / total) * 100 : 0;
  return (
    <div
      style={{
        height: 2,
        background: 'var(--border)',
        borderRadius: 2,
        overflow: 'hidden',
      }}
    >
      <div
        style={{
          height: '100%',
          width: `${pct}%`,
          background: color,
          borderRadius: 2,
          transition: 'width 0.5s ease',
        }}
      />
    </div>
  );
}

