// ─── TODAY SCREEN ─────────────────────────────────────────────────────────────
function TodayScreen({ who }) {
  const [tasks, setTasks] = useState([]);
  const [completions, setCompletions] = useState(new Set());
  const [tab, setTab] = useState('morning');
  const [loading, setLoading] = useState(true);
  const [todayPlans, setTodayPlans] = useState([]);
  const [plansLoading, setPlansLoading] = useState(true);

  const pKey = dailyKey();
  const color = tab === 'morning' ? 'var(--morning)' : 'var(--evening)';

  // Today's date in DD/MM/YYYY for matching next actions
  const todayDate = (() => {
    const d = new Date();
    return `${String(d.getDate()).padStart(2, '0')}/${String(
      d.getMonth() + 1
    ).padStart(2, '0')}/${d.getFullYear()}`;
  })();

  // Meeting date from localStorage
  const meetingDate = localStorage.getItem('hb_meeting_date') || '';
  const meetingIsToday = meetingDate === new Date().toISOString().split('T')[0];

  useEffect(() => {
    const load = async () => {
      setLoading(true);
      const [{ data: t }, { data: c }] = await Promise.all([
        sb
          .from('routine_tasks')
          .select('*')
          .in('type', ['morning', 'evening'])
          .order('sort_order'),
        sb.from('routine_completions').select('task_id').eq('period_key', pKey),
      ]);
      setTasks(t || []);
      setCompletions(new Set((c || []).map((r) => r.task_id)));
      setLoading(false);
    };
    load();

    const sub = sb
      .channel('today_completions')
      .on(
        'postgres_changes',
        { event: '*', schema: 'public', table: 'routine_completions' },
        () => {
          sb.from('routine_completions')
            .select('task_id')
            .eq('period_key', pKey)
            .then(({ data }) => {
              setCompletions(new Set((data || []).map((r) => r.task_id)));
            });
        }
      )
      .subscribe();

    return () => sb.removeChannel(sub);
  }, [pKey]);

  // Load today's plans: next actions due today + dated monthly tasks due today
  useEffect(() => {
    const loadPlans = async () => {
      setPlansLoading(true);
      const { data: actions } = await sb
        .from('next_actions')
        .select('*')
        .eq('done', false)
        .eq('due_date', todayDate);
      const { data: monthly } = await sb
        .from('routine_tasks')
        .select('*')
        .eq('type', 'monthly')
        .not('due_date', 'is', null)
        .eq('due_date', todayDate);
      setTodayPlans([...(actions || []), ...(monthly || [])]);
      setPlansLoading(false);
    };
    loadPlans();

    const sub = sb
      .channel('today_plans_rt')
      .on(
        'postgres_changes',
        { event: '*', schema: 'public', table: 'next_actions' },
        loadPlans
      )
      .subscribe();
    return () => sb.removeChannel(sub);
  }, [todayDate]);

  const toggle = async (taskId) => {
    const done = completions.has(taskId);
    if (done) {
      await sb
        .from('routine_completions')
        .delete()
        .eq('task_id', taskId)
        .eq('period_key', pKey);
      setCompletions((s) => {
        const n = new Set(s);
        n.delete(taskId);
        return n;
      });
    } else {
      await sb
        .from('routine_completions')
        .upsert({ task_id: taskId, period_key: pKey, completed_by: who });
      setCompletions((s) => new Set([...s, taskId]));
    }
  };

  const visible = tasks.filter((t) => t.type === tab);
  const doneCount = visible.filter((t) => completions.has(t.id)).length;
  const hour = new Date().getHours();
  const greeting = hour < 12 ? 'Morning' : hour < 18 ? 'Afternoon' : 'Evening';

  const TABS = [
    { key: 'morning', label: '☀ Morning', color: 'var(--morning)' },
    { key: 'evening', label: '☾ Evening', color: 'var(--evening)' },
    { key: 'plans', label: '◈ Plans', color: 'var(--admin)' },
  ];

  return (
    <div className="fade" style={{ padding: '0 0 100px' }}>
      <div style={{ padding: '32px 20px 16px' }}>
        <div
          style={{
            fontSize: 11,
            color: 'var(--muted)',
            fontFamily: "'DM Mono', monospace",
            letterSpacing: '1px',
            textTransform: 'uppercase',
            marginBottom: 6,
          }}
        >
          {new Date().toLocaleDateString('en-GB', {
            weekday: 'long',
            day: 'numeric',
            month: 'long',
            timeZone: 'Europe/Malta',
          })}
        </div>
        <div
          style={{
            fontFamily: "'Cormorant Garamond', Georgia, serif",
            fontSize: 36,
            fontWeight: 300,
            color: 'var(--text)',
            letterSpacing: '-0.5px',
            lineHeight: 1.1,
          }}
        >
          {greeting}, {who === 'alba' ? 'Alba' : 'Josh'}
        </div>
      </div>

      {/* 3 tab switcher */}
      <div style={{ padding: '0 20px 20px', display: 'flex', gap: 6 }}>
        {TABS.map((t) => (
          <button
            key={t.key}
            onClick={() => setTab(t.key)}
            style={{
              flex: 1,
              padding: '10px 4px',
              borderRadius: 12,
              background: tab === t.key ? t.color : 'var(--surface)',
              border: `1px solid ${
                tab === t.key ? 'transparent' : 'var(--border)'
              }`,
              color: tab === t.key ? '#fff' : 'var(--muted)',
              fontSize: 12,
              fontWeight: tab === t.key ? 500 : 400,
              transition: 'all 0.2s',
              boxShadow:
                tab === t.key
                  ? `0 4px 16px ${t.color}44`
                  : '0 1px 4px #2C282508',
            }}
          >
            {t.label}
          </button>
        ))}
      </div>

      {/* Morning / Evening routine */}
      {(tab === 'morning' || tab === 'evening') && (
        <>
          <div style={{ padding: '0 20px 14px' }}>
            <div
              style={{
                display: 'flex',
                justifyContent: 'space-between',
                alignItems: 'center',
                marginBottom: 7,
              }}
            >
              <span
                style={{
                  fontSize: 10,
                  fontFamily: "'DM Mono', monospace",
                  color,
                  textTransform: 'uppercase',
                  letterSpacing: '1px',
                }}
              >
                {tab === 'morning' ? 'Morning Routine' : 'Evening Shutdown'}
              </span>
              <span
                style={{
                  fontSize: 10,
                  fontFamily: "'DM Mono', monospace",
                  color: 'var(--muted)',
                }}
              >
                {doneCount}/{visible.length}
              </span>
            </div>
            <Bar done={doneCount} total={visible.length} color={color} />
            {doneCount === visible.length && visible.length > 0 && (
              <div
                style={{
                  marginTop: 10,
                  padding: '10px 16px',
                  background: `${color}12`,
                  borderRadius: 10,
                  color,
                  border: `1px solid ${color}22`,
                  fontStyle: 'italic',
