                  color={color}
                  sub={t.sub_items}
                />
              ))}
            </div>
          )}
        </>
      )}

      {/* Today's Plans */}
      {tab === 'plans' && (
        <div style={{ padding: '0 20px' }}>
          {plansLoading ? (
            <Spinner />
          ) : (
            <>
              {/* Meeting block if scheduled today */}
              {meetingIsToday && (
                <div
                  style={{
                    marginBottom: 16,
                    padding: '14px 16px',
                    borderRadius: 12,
                    background: 'var(--surface)',
                    border: `1px solid var(--josh)44`,
                    boxShadow: '0 1px 6px #2C282508',
