                              : t.context === 'errand'
                              ? '🚗'
                              : '🏠'}{' '}
                            {t.context}
                          </div>
                        )}
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                !meetingIsToday && (
                  <div
                    style={{
                      padding: '14px',
                      borderRadius: 12,
                      background: 'var(--surface)',
                      border: '1px solid var(--border)',
                      fontSize: 13,
                      color: 'var(--muted)',
                      textAlign: 'center',
                    }}
                  >
                    Nothing specific scheduled for today ✦
                  </div>
                )
              )}
            </>
          )}
        </div>
      )}
    </div>
  );
}

// ─── JOSH MEETING BLOCK ───────────────────────────────────────────────────────
function JoshMeetingBlock({ isWed }) {
  const [items, setItems] = useState([]);
  const [adding, setAdding] = useState(false);
  const [newText, setNewText] = useState('');
  const [newNotes, setNewNotes] = useState('');
  const [loading, setLoading] = useState(true);
  const [editingDate, setEditingDate] = useState(false);
  const [meetingDate, setMeetingDate] = useState(
    () => localStorage.getItem('hb_meeting_date') || ''
  );

  const load = useCallback(async () => {
    const { data, error } = await sb
      .from('josh_meeting_items')
      .select('*')
      .eq('done', false)
      .order('created_at');
    if (error) console.error('josh meeting load error:', error);
    setItems(data || []);
    setLoading(false);
  }, []);

  useEffect(() => {
    load();
    const sub = sb
      .channel('josh_meeting_rt')
      .on(
        'postgres_changes',
        { event: '*', schema: 'public', table: 'josh_meeting_items' },
        load
      )
      .subscribe();
    return () => sb.removeChannel(sub);
  }, [load]);

  const saveDate = (d) => {
    localStorage.setItem('hb_meeting_date', d);
    setMeetingDate(d);
    setEditingDate(false);
  };

  const addItem = async () => {
    if (!newText.trim()) return;
    const newItem = {
      text: newText.trim(),
      notes: newNotes.trim() || '',
      done: false,
    };
    const { data, error } = await sb
      .from('josh_meeting_items')
      .insert(newItem)
      .select('id, text, notes, done')
      .single();
    if (error) console.error('josh meeting add error:', error);
    setItems((is) => [...is, data || { ...newItem, id: `jm_${Date.now()}` }]);
    setNewText('');
    setNewNotes('');
    setAdding(false);
  };

  const tickItem = async (item) => {
    await sb
      .from('josh_meeting_items')
      .update({ done: true })
      .eq('id', item.id);
    await sb
      .from('history_items')
      .insert({
        text: item.text,
        notes: item.notes || '',
        source: 'josh_meeting',
      });
    setItems((is) => is.filter((i) => i.id !== item.id));
  };

  const deleteItem = async (id) => {
    await sb.from('josh_meeting_items').delete().eq('id', id);
    setItems((is) => is.filter((i) => i.id !== id));
  };

  const dateLabel = meetingDate
    ? new Date(meetingDate).toLocaleDateString('en-GB', {
        weekday: 'short',
        day: 'numeric',
        month: 'short',
      })
    : 'Wednesday';

  return (
    <div style={{ padding: '0 20px 16px' }}>
      {/* Section label matching other sections */}
      <SectionLabel text="Alba & Josh Weekly" color="var(--josh)" />

      <div
        style={{
          borderRadius: 12,
          background: 'var(--surface)',
          border: '1px solid var(--border)',
          boxShadow: '0 1px 4px #2C282506',
          overflow: 'hidden',
        }}
      >
        {/* Header bar */}
        <div
          style={{
            padding: '12px 14px',
            borderBottom: '1px solid var(--border)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
            background: `var(--josh)08`,
          }}
        >
          <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
            <div
              style={{
                width: 7,
                height: 7,
                borderRadius: '50%',
                background: 'var(--josh)',
              }}
            />
            {editingDate ? (
              <input
                type="date"
                autoFocus
                defaultValue={meetingDate}
                onChange={(e) => saveDate(e.target.value)}
                onBlur={(e) => saveDate(e.target.value)}
                style={{
                  background: 'none',
                  border: 'none',
                  color: 'var(--josh)',
                  fontSize: 12,
                  fontFamily: "'DM Mono', monospace",
                  outline: 'none',
                  cursor: 'pointer',
                }}
              />
            ) : (
              <button
                onClick={() => setEditingDate(true)}
                style={{
                  background: 'none',
                  border: 'none',
                  padding: 0,
                  display: 'flex',
                  alignItems: 'center',
                  gap: 6,
                }}
              >
                <span
                  style={{
                    fontSize: 12,
                    fontFamily: "'DM Mono', monospace",
                    color: 'var(--josh)',
                    letterSpacing: '0.5px',
                  }}
                >
                  {dateLabel}
                </span>
                <span style={{ fontSize: 10, color: 'var(--muted2)' }}>✎</span>
              </button>
            )}
            {isWed && (
              <span
                style={{
                  fontSize: 9,
                  padding: '2px 6px',
                  borderRadius: 20,
                  background: 'var(--josh)',
                  color: '#fff',
                  fontFamily: "'DM Mono', monospace",
                }}
              >
                Today
              </span>
            )}
          </div>
          <span
            style={{
              fontSize: 10,
              fontFamily: "'DM Mono', monospace",
              color: 'var(--muted2)',
            }}
          >
            {items.length} items
          </span>
        </div>

        {/* Items */}
        <div style={{ padding: '10px 14px 14px' }}>
          {loading ? (
            <Spinner />
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
              {items.map((item) => (
                <div
                  key={item.id}
                  style={{
                    display: 'flex',
                    alignItems: 'flex-start',
                    gap: 10,
                    padding: '10px 12px',
                    background: 'var(--bg)',
                    borderRadius: 10,
                    border: '1px solid var(--border)',
                  }}
                >
                  <Checkbox
                    checked={false}
                    onChange={() => tickItem(item)}
                    color="var(--josh)"
                    size={18}
                  />
                  <div style={{ flex: 1 }}>
                    <div
                      style={{
                        fontSize: 13,
                        color: 'var(--text)',
                        fontWeight: 400,
                      }}
                    >
                      {item.text}
                    </div>
                    {item.notes && (
                      <div
                        style={{
                          fontSize: 11,
                          color: 'var(--muted)',
                          marginTop: 3,
                          lineHeight: 1.5,
                        }}
                      >
                        {item.notes}
                      </div>
                    )}
                  </div>
                  <button
                    onClick={() => deleteItem(item.id)}
                    style={{
                      background: 'none',
                      border: 'none',
                      color: 'var(--muted2)',
                      fontSize: 14,
                      padding: '0 2px',
                      flexShrink: 0,
                    }}
                  >
                    ×
                  </button>
                </div>
              ))}

              {items.length === 0 && !adding && (
                <div
                  style={{
                    fontSize: 12,
                    color: 'var(--muted2)',
                    fontFamily: "'DM Mono', monospace",
                    padding: '8px 2px',
                    textAlign: 'center',
                  }}
                >
                  Nothing to discuss yet
                </div>
              )}

              {!adding ? (
                <button
                  onClick={() => setAdding(true)}
                  style={{
                    padding: '9px',
                    background: 'none',
                    marginTop: 2,
                    border: `1.5px dashed var(--josh)44`,
                    borderRadius: 10,
                    color: 'var(--josh)',
                    fontSize: 12,
                  }}
                >
                  + Add item
                </button>
              ) : (
                <div
                  style={{
                    display: 'flex',
                    flexDirection: 'column',
                    gap: 6,
                    background: 'var(--bg)',
                    borderRadius: 10,
                    padding: 12,
                    border: `1px solid var(--josh)33`,
                    marginTop: 2,
                  }}
                >
                  <input
                    autoFocus
                    value={newText}
                    onChange={(e) => setNewText(e.target.value)}
                    onKeyDown={(e) => {
                      if (e.key === 'Enter') addItem();
                      if (e.key === 'Escape') setAdding(false);
                    }}
                    placeholder="What to discuss…"
                    style={{
                      background: 'var(--surface)',
                      border: '1px solid var(--border)',
                      borderRadius: 8,
                      padding: '8px 11px',
                      color: 'var(--text)',
                      fontSize: 13,
                      outline: 'none',
                    }}
                  />
                  <input
                    value={newNotes}
                    onChange={(e) => setNewNotes(e.target.value)}
                    placeholder="Notes (optional)"
                    style={{
                      background: 'var(--surface)',
                      border: '1px solid var(--border)',
                      borderRadius: 8,
                      padding: '8px 11px',
                      color: 'var(--text)',
                      fontSize: 13,
                      outline: 'none',
                    }}
                  />
                  <div style={{ display: 'flex', gap: 6 }}>
                    <button
                      onClick={addItem}
                      style={{
                        flex: 1,
                        padding: '8px',
                        background: 'var(--josh)',
                        border: 'none',
                        borderRadius: 8,
                        color: '#fff',
                        fontSize: 12,
                        fontWeight: 500,
                      }}
                    >
                      Add
                    </button>
                    <button
                      onClick={() => {
                        setAdding(false);
                        setNewText('');
                        setNewNotes('');
                      }}
                      style={{
                        padding: '8px 12px',
                        background: 'var(--surface2)',
                        border: 'none',
                        borderRadius: 8,
                        color: 'var(--muted)',
                        fontSize: 12,
                      }}
                    >
                      Cancel
                    </button>
                  </div>
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

// ─── WEEK SCREEN ──────────────────────────────────────────────────────────────
function WeekScreen({ who }) {
  const [roomTasks, setRoomTasks] = useState([]);
  const [otherTasks, setOtherTasks] = useState([]);
  const [completions, setCompletions] = useState(new Set());
  const [openRoom, setOpenRoom] = useState(null);
  const [loading, setLoading] = useState(true);
  const pKey = weeklyKey();

  useEffect(() => {
    const load = async () => {
      setLoading(true);
      const [{ data: rt }, { data: ot }, { data: c }] = await Promise.all([
        sb
          .from('routine_tasks')
          .select('*')
          .eq('type', 'weekly_room')
          .order('sort_order'),
        sb
          .from('routine_tasks')
          .select('*')
          .eq('type', 'weekly_other')
          .order('sort_order'),
        sb.from('routine_completions').select('task_id').eq('period_key', pKey),
      ]);
      setRoomTasks(rt || []);
      setOtherTasks(ot || []);
      setCompletions(new Set((c || []).map((r) => r.task_id)));
      setLoading(false);
    };
    load();

    const sub = sb
      .channel('week_completions')
      .on(
        'postgres_changes',
        { event: '*', schema: 'public', table: 'routine_completions' },
        () => {
          sb.from('routine_completions')
            .select('task_id')
            .eq('period_key', pKey)
            .then(({ data }) => {
              setCompletions(new Set((data || []).map((r) => r.task_id)));
            });
        }
      )
      .subscribe();

    return () => sb.removeChannel(sub);
  }, [pKey]);

  const toggle = async (taskId) => {
    const done = completions.has(taskId);
    if (done) {
      await sb
        .from('routine_completions')
        .delete()
        .eq('task_id', taskId)
        .eq('period_key', pKey);
      setCompletions((s) => {
        const n = new Set(s);
        n.delete(taskId);
        return n;
      });
    } else {
      await sb
        .from('routine_completions')
        .upsert({ task_id: taskId, period_key: pKey, completed_by: who });
      setCompletions((s) => new Set([...s, taskId]));
    }
  };

  const isWed = new Date().getDay() === 3;
  const totalRoomDone = roomTasks.filter((t) => completions.has(t.id)).length;
  const otherDone = otherTasks.filter((t) => completions.has(t.id)).length;

  const roomTasksFor = (roomId) =>
    roomTasks.filter((t) => t.id.startsWith(`wr_${roomId}_`));

  return (
    <div className="fade" style={{ padding: '0 0 100px' }}>
      <div style={{ padding: '32px 20px 18px' }}>
        <div
          style={{
            fontFamily: "'Cormorant Garamond', Georgia, serif",
            fontSize: 34,
            fontWeight: 300,
            color: 'var(--text)',
            marginBottom: 4,
            letterSpacing: '-0.3px',
          }}
        >
          This Week
        </div>
        <div
          style={{
            fontSize: 10,
            color: 'var(--muted)',
            fontFamily: "'DM Mono', monospace",
            letterSpacing: '1px',
            textTransform: 'uppercase',
          }}
        >
          Resets every Monday
        </div>
      </div>

      {loading ? (
        <Spinner />
      ) : (
        <>
          {/* Cleaning */}
          <div style={{ padding: '0 20px 16px' }}>
            <SectionLabel
              text="Cleaning"
              color="var(--chores)"
              done={totalRoomDone}
              total={roomTasks.length}
            />
            <div
              style={{
                display: 'flex',
                flexDirection: 'column',
                gap: 6,
                marginTop: 12,
              }}
            >
              {ROOMS.map((room) => {
                const rts = roomTasksFor(room.id);
                const done = rts.filter((t) => completions.has(t.id)).length;
                const allDone = rts.length > 0 && done === rts.length;
                const isOpen = openRoom === room.id;
                return (
                  <div
                    key={room.id}
                    style={{
                      borderRadius: 12,
                      overflow: 'hidden',
                      border: `1px solid var(--border)`,
                      background: 'var(--surface)',
                      boxShadow: '0 1px 4px #2C282506',
                    }}
                  >
                    <button
                      onClick={() => setOpenRoom(isOpen ? null : room.id)}
                      style={{
                        width: '100%',
                        padding: '13px 15px',
                        background: 'none',
                        border: 'none',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'space-between',
                        color: allDone ? 'var(--muted2)' : 'var(--text)',
                      }}
                    >
                      <div
                        style={{
                          display: 'flex',
                          alignItems: 'center',
                          gap: 10,
                        }}
                      >
                        <div
                          style={{
                            width: 7,
                            height: 7,
                            borderRadius: '50%',
                            background: allDone
                              ? 'var(--muted)'
                              : 'var(--chores)',
                            flexShrink: 0,
                          }}
                        />
                        <span
                          style={{
                            fontSize: 14,
                            textAlign: 'left',
                            textDecoration: allDone ? 'line-through' : 'none',
                          }}
                        >
                          {room.label}
                        </span>
                      </div>
                      <div
                        style={{
                          display: 'flex',
                          alignItems: 'center',
                          gap: 8,
                        }}
                      >
                        <span
                          style={{
                            fontSize: 10,
                            fontFamily: "'DM Mono', monospace",
                            color: 'var(--muted)',
                          }}
                        >
                          {done}/{rts.length}
                        </span>
                        <span
                          style={{
                            fontSize: 10,
                            color: 'var(--muted)',
                            transform: isOpen ? 'rotate(180deg)' : 'none',
                            transition: '0.2s',
                          }}
                        >
                          ▾
                        </span>
                      </div>
                    </button>
                    {isOpen && (
                      <div
                        style={{
                          borderTop: '1px solid var(--border)',
                          padding: '8px 14px 12px',
                        }}
                      >
                        {rts.map((t) => (
                          <div
                            key={t.id}
                            style={{
                              display: 'flex',
                              alignItems: 'center',
                              gap: 10,
                              padding: '7px 0',
                            }}
                          >
                            <Checkbox
                              checked={completions.has(t.id)}
                              onChange={() => toggle(t.id)}
                              color="var(--chores)"
                              size={18}
                            />
                            <span
                              style={{
                                fontSize: 13,
                                color: completions.has(t.id)
                                  ? 'var(--muted)'
                                  : 'var(--text)',
                                textDecoration: completions.has(t.id)
                                  ? 'line-through'
                                  : 'none',
                              }}
                            >
                              {t.text}
                            </span>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          </div>

          {/* Josh meeting */}
          <JoshMeetingBlock isWed={isWed} />

          {/* Weekly other */}
          <div style={{ padding: '0 20px' }}>
            <SectionLabel
              text="Weekly Admin"
              color="var(--admin)"
              done={otherDone}
              total={otherTasks.length}
            />
            <div
              style={{
                display: 'flex',
                flexDirection: 'column',
                gap: 2,
                marginTop: 12,
              }}
            >
              {otherTasks.map((t) => (
                <TaskRow
                  key={t.id}
                  text={t.text}
                  done={completions.has(t.id)}
                  onToggle={() => toggle(t.id)}
                  color="var(--admin)"
                />
              ))}
            </div>
          </div>
        </>
      )}
    </div>
  );
}

// ─── EDITABLE TASK ROW ────────────────────────────────────────────────────────
function EditableTaskRow({ task, onToggle, onSave, onDelete, color, badge }) {
  const [editing, setEditing] = useState(false);
  const [editText, setEditText] = useState(task.text);
  const [editContext, setEditContext] = useState(task.context || 'phone');
  const [editDate, setEditDate] = useState(task.due_date || '');

  const save = () => {
    if (editText.trim()) onSave(task, editText.trim(), editContext, editDate);
    setEditing(false);
  };

  if (editing)
    return (
      <div
        style={{
          display: 'flex',
          flexDirection: 'column',
          gap: 6,
          padding: '10px 12px',
          background: 'var(--surface)',
          borderRadius: 12,
          border: `1px solid ${color}44`,
          marginBottom: 3,
          boxShadow: '0 2px 8px #2C282510',
        }}
      >
        <input
          autoFocus
          value={editText}
          onChange={(e) => setEditText(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === 'Enter') save();
            if (e.key === 'Escape') setEditing(false);
          }}
          style={{
            background: 'var(--bg)',
            border: '1px solid var(--border)',
            borderRadius: 8,
            padding: '8px 11px',
            color: 'var(--text)',
            fontSize: 13,
            outline: 'none',
          }}
        />
        <div style={{ display: 'flex', gap: 5 }}>
          {[
            ['phone', '📱'],
            ['errand', '🚗'],
            ['home', '🏠'],
          ].map(([k, l]) => (
            <button
              key={k}
              onClick={() => setEditContext(k)}
              style={{
                flex: 1,
                padding: '6px',
                borderRadius: 8,
                border: 'none',
                fontSize: 13,
                background: editContext === k ? color : 'var(--surface2)',
                color: editContext === k ? '#fff' : 'var(--muted)',
              }}
            >
              {l}
            </button>
          ))}
        </div>
        <input
          value={editDate}
          onChange={(e) => setEditDate(e.target.value)}
          placeholder="Due date (DD/MM/YYYY) — optional"
          style={{
            background: 'var(--bg)',
            border: '1px solid var(--border)',
            borderRadius: 8,
            padding: '7px 11px',
            color: 'var(--text)',
            fontSize: 12,
            outline: 'none',
          }}
        />
        <div style={{ display: 'flex', gap: 6 }}>
          <button
            onClick={save}
            style={{
              flex: 1,
              padding: '7px',
              background: color,
              border: 'none',
              borderRadius: 8,
              color: '#fff',
              fontSize: 12,
              fontWeight: 500,
            }}
          >
            Save
          </button>
          <button
            onClick={() => setEditing(false)}
            style={{
              padding: '7px 12px',
              background: 'var(--surface2)',
              border: 'none',
              borderRadius: 8,
              color: 'var(--muted)',
              fontSize: 12,
            }}
          >
            Cancel
          </button>
        </div>
      </div>
    );

  return (
    <div
      style={{
        marginBottom: 3,
        display: 'flex',
        alignItems: 'center',
        gap: 8,
        padding: '11px 14px',
        borderRadius: 12,
        background: 'var(--surface)',
        border: `1px solid ${task.overdue ? '#C44A4A22' : 'var(--border)'}`,
        boxShadow: '0 1px 4px #2C282508',
      }}
    >
      <Checkbox checked={false} onChange={onToggle} color={color} />
      <div style={{ flex: 1 }} onClick={() => setEditing(true)}>
        <div
          style={{
            display: 'flex',
            alignItems: 'center',
            gap: 6,
            flexWrap: 'wrap',
          }}
        >
          <span style={{ fontSize: 14, color: 'var(--text)' }}>
            {task.text}
          </span>
          {task.overdue && (
            <span
              style={{
                fontSize: 9,
                padding: '2px 7px',
                borderRadius: 20,
                background: '#C44A4A15',
                color: 'var(--danger)',
                fontFamily: "'DM Mono', monospace",
              }}
            >
              overdue {task.due_date}
            </span>
          )}
          {task.due_date && !task.overdue && (
            <span
              style={{
                fontSize: 9,
                padding: '2px 7px',
                borderRadius: 20,
                background: 'var(--surface2)',
                color: 'var(--muted)',
                fontFamily: "'DM Mono', monospace",
              }}
            >
              {task.due_date}
            </span>
          )}
          {badge && <span style={{ fontSize: 11 }}>{badge}</span>}
        </div>
      </div>
      <button
        onClick={() => setEditing(true)}
        style={{
          background: 'none',
          border: 'none',
          color: 'var(--muted2)',
          fontSize: 12,
          padding: '0 2px',
        }}
      >
        ✎
      </button>
      <button
        onClick={() => onDelete(task.id)}
        style={{
          background: 'none',
          border: 'none',
          color: 'var(--muted2)',
          fontSize: 14,
          padding: '0 2px',
        }}
      >
        ×
      </button>
    </div>
  );
}

