  const [newWF, setNewWF] = useState('');
  const [loading, setLoading] = useState(true);

  const load = useCallback(async () => {
    const [{ data: t }, { data: w }] = await Promise.all([
      sb
        .from('next_actions')
        .select('*')
        .order('sort_order')
        .order('created_at'),
      sb.from('waiting_for').select('*').order('created_at'),
    ]);
    setTasks(t || []);
    setWaiting(w || []);
    setLoading(false);
  }, []);

  useEffect(() => {
    load();
    const sub = sb
      .channel('tasks_rt')
      .on(
        'postgres_changes',
        { event: '*', schema: 'public', table: 'next_actions' },
        load
      )
      .on(
        'postgres_changes',
        { event: '*', schema: 'public', table: 'waiting_for' },
        load
      )
      .subscribe();
    return () => sb.removeChannel(sub);
  }, [load]);

  const toggle = async (task) => {
    const newDone = !task.done;
    await sb.from('next_actions').update({ done: newDone }).eq('id', task.id);
    if (newDone) {
      await sb
        .from('history_items')
        .insert({
          text: task.text,
          notes: task.due_date || '',
          source: 'next_action',
        });
    }
    setTasks((ts) =>
      ts.map((t) => (t.id === task.id ? { ...t, done: newDone } : t))
    );
  };

  const saveTask = async (task, newText, newContext, newDate) => {
    await sb
      .from('next_actions')
      .update({ text: newText, context: newContext, due_date: newDate || null })
      .eq('id', task.id);
    setTasks((ts) =>
      ts.map((t) =>
        t.id === task.id
          ? {
              ...t,
              text: newText,
              context: newContext,
              due_date: newDate || null,
            }
          : t
      )
    );
  };

  const deleteTask = async (id) => {
    await sb.from('next_actions').delete().eq('id', id);
    setTasks((ts) => ts.filter((t) => t.id !== id));
  };

  const addTask = async () => {
    if (!newText.trim()) return;
    const newItem = {
      id: `na_${Date.now()}`,
      text: newText.trim(),
      assigned: 'alba',
      context: newContext,
      due_date: newDate.trim() || null,
      done: false,
    };
    const { data, error } = await sb
      .from('next_actions')
      .insert(newItem)
      .select('id, text, assigned, context, due_date, done, overdue')
      .single();
    if (error) console.error('addTask error:', error);
    setTasks((ts) => [...ts, data || newItem]);
    setNewText('');
    setNewDate('');
    setAdding(false);
  };

  const addWF = async () => {
    if (!newWF.trim()) return;
    const { data, error } = await sb
      .from('waiting_for')
      .insert({ text: newWF.trim() })
      .select('id, text')
      .single();
    if (error) console.error('addWF error:', error);
    setWaiting((ws) => [
      ...ws,
      data || { id: `wf_${Date.now()}`, text: newWF.trim() },
    ]);
    setNewWF('');
    setAddingWF(false);
  };

  const removeWF = async (id) => {
    await sb.from('waiting_for').delete().eq('id', id);
    setWaiting((ws) => ws.filter((w) => w.id !== id));
  };

  const tickWF = async (item) => {
    await sb.from('waiting_for').delete().eq('id', item.id);
    await sb
      .from('history_items')
      .insert({ text: item.text, notes: '', source: 'waiting_for' });
    setWaiting((ws) => ws.filter((w) => w.id !== item.id));
  };

  const filtered =
    context === 'all' ? tasks : tasks.filter((t) => t.context === context);
  const active = filtered.filter((t) => !t.done);
  const done = filtered.filter((t) => t.done);

  return (
    <div className="fade" style={{ padding: '0 0 100px' }}>
      <div style={{ padding: '32px 20px 18px' }}>
        <div
          style={{
            fontFamily: "'Cormorant Garamond', Georgia, serif",
            fontSize: 34,
            fontWeight: 300,
            color: 'var(--text)',
            marginBottom: 4,
            letterSpacing: '-0.3px',
          }}
        >
          Next Actions
        </div>
        <div
          style={{
            fontSize: 10,
            color: 'var(--muted)',
            fontFamily: "'DM Mono', monospace",
            letterSpacing: '1px',
            textTransform: 'uppercase',
          }}
        >
          {active.length} to do
        </div>
      </div>

      <div style={{ padding: '0 20px 16px', display: 'flex', gap: 6 }}>
        {CONTEXTS.map((c) => (
          <button
            key={c.key}
            onClick={() => setContext(c.key)}
            style={{
              flex: 1,
              padding: '8px 4px',
              borderRadius: 20,
              background: context === c.key ? 'var(--text)' : 'var(--surface)',
              border: `1px solid ${
                context === c.key ? 'transparent' : 'var(--border)'
              }`,
              color: context === c.key ? 'var(--bg)' : 'var(--muted)',
              fontSize: 11,
              fontWeight: context === c.key ? 500 : 400,
              transition: 'all 0.18s',
            }}
          >
            {c.label}
          </button>
        ))}
      </div>

      {loading ? (
        <Spinner />
      ) : (
        <div
          style={{
            padding: '0 20px',
            display: 'flex',
            flexDirection: 'column',
            gap: 2,
          }}
        >
          {active.map((t) => (
            <EditableTaskRow
              key={t.id}
              task={t}
              onToggle={() => toggle(t)}
              onSave={saveTask}
              onDelete={deleteTask}
              color="var(--admin)"
              badge={
                context === 'all' && t.context
                  ? t.context === 'phone'
                    ? '📱'
                    : t.context === 'errand'
                    ? '🚗'
                    : '🏠'
                  : null
              }
            />
          ))}
        </div>
      )}

      <div style={{ padding: '12px 20px 0' }}>
        {!adding ? (
          <button
            onClick={() => setAdding(true)}
            style={{
              width: '100%',
              padding: '10px',
              background: 'none',
              border: '1.5px dashed var(--border)',
              borderRadius: 10,
              color: 'var(--muted)',
              fontSize: 13,
            }}
          >
            + Add action
          </button>
        ) : (
          <div
            style={{
              display: 'flex',
              flexDirection: 'column',
              gap: 8,
              background: 'var(--surface)',
              borderRadius: 14,
              padding: 16,
              border: '1px solid var(--border)',
              boxShadow: '0 2px 12px #2C282510',
            }}
          >
            <input
              autoFocus
              value={newText}
              onChange={(e) => setNewText(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === 'Enter') addTask();
                if (e.key === 'Escape') setAdding(false);
              }}
              placeholder="What needs doing?"
              style={{
                background: 'var(--bg)',
                border: '1px solid var(--border)',
                borderRadius: 8,
                padding: '10px 12px',
                color: 'var(--text)',
                fontSize: 14,
                outline: 'none',
              }}
            />
            <div style={{ display: 'flex', gap: 6 }}>
              {[
                ['phone', '📱 Phone'],
                ['errand', '🚗 Errand'],
                ['home', '🏠 Home'],
              ].map(([k, l]) => (
                <button
                  key={k}
                  onClick={() => setNewContext(k)}
                  style={{
                    flex: 1,
                    padding: '7px 4px',
                    borderRadius: 8,
                    border: 'none',
                    background:
                      newContext === k ? 'var(--admin)' : 'var(--surface2)',
                    color: newContext === k ? '#0F0F0F' : 'var(--muted)',
                    fontSize: 12,
                  }}
                >
                  {l}
                </button>
              ))}
            </div>
            <input
              value={newDate}
              onChange={(e) => setNewDate(e.target.value)}
              placeholder="Due date (DD/MM/YYYY) — optional"
              style={{
                background: 'var(--surface2)',
                border: '1px solid var(--border)',
                borderRadius: 8,
                padding: '8px 12px',
                color: 'var(--text)',
                fontSize: 13,
                outline: 'none',
              }}
            />
            <div style={{ display: 'flex', gap: 8 }}>
              <button
                onClick={addTask}
                style={{
                  flex: 1,
                  padding: '9px',
                  background: 'var(--admin)',
                  border: 'none',
                  borderRadius: 8,
                  color: '#0F0F0F',
                  fontSize: 13,
                  fontWeight: 500,
                }}
              >
                Add
              </button>
              <button
                onClick={() => setAdding(false)}
                style={{
                  padding: '9px 16px',
                  background: 'var(--surface2)',
                  border: 'none',
                  borderRadius: 8,
                  color: 'var(--muted)',
                  fontSize: 13,
                }}
              >
                Cancel
              </button>
            </div>
          </div>
        )}
      </div>

      {done.length > 0 && (
        <div style={{ padding: '20px 20px 0' }}>
          <div
            style={{
              fontSize: 10,
              fontFamily: "'DM Mono', monospace",
              color: 'var(--muted)',
              marginBottom: 8,
              textTransform: 'uppercase',
              letterSpacing: '1px',
            }}
          >
            Done · {done.length}
          </div>
          <div
            style={{
              display: 'flex',
              flexDirection: 'column',
              gap: 2,
              opacity: 0.45,
            }}
          >
            {done.map((t) => (
              <TaskRow
                key={t.id}
                text={t.text}
                done={true}
                onToggle={() => toggle(t)}
                color="var(--admin)"
              />
            ))}
          </div>
        </div>
      )}

      <div style={{ padding: '24px 20px 0' }}>
        <div
          style={{
            fontSize: 10,
            fontFamily: "'DM Mono', monospace",
            color: 'var(--muted)',
            marginBottom: 10,
            textTransform: 'uppercase',
            letterSpacing: '1px',
          }}
        >
          Waiting For
        </div>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
          {waiting.map((w) => (
            <div
              key={w.id}
              style={{
                display: 'flex',
                alignItems: 'center',
                gap: 10,
                padding: '10px 14px',
                background: 'var(--surface)',
                borderRadius: 10,
                border: '1px solid var(--border)',
                boxShadow: '0 1px 4px #2C282506',
              }}
            >
              <Checkbox
                checked={false}
                onChange={() => tickWF(w)}
                color="var(--admin)"
                size={18}
              />
              <span style={{ flex: 1, fontSize: 14, color: 'var(--text)' }}>
                {w.text}
              </span>
              <button
                onClick={() => removeWF(w.id)}
                style={{
                  background: 'none',
                  border: 'none',
                  color: 'var(--muted2)',
                  fontSize: 14,
                }}
                title="Delete permanently"
              >
                ×
              </button>
            </div>
          ))}
          {!addingWF ? (
            <button
              onClick={() => setAddingWF(true)}
              style={{
                padding: '9px',
                background: 'none',
                border: '1.5px dashed var(--border)',
                borderRadius: 10,
                color: 'var(--muted)',
                fontSize: 13,
              }}
            >
              + Add waiting for
            </button>
          ) : (
            <div style={{ display: 'flex', gap: 8 }}>
              <input
                autoFocus
                value={newWF}
                onChange={(e) => setNewWF(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === 'Enter') addWF();
                  if (e.key === 'Escape') setAddingWF(false);
                }}
                placeholder="Waiting for…"
                style={{
                  flex: 1,
                  background: 'var(--surface)',
                  border: '1px solid var(--border)',
                  borderRadius: 8,
                  padding: '9px 12px',
                  color: 'var(--text)',
                  fontSize: 14,
                  outline: 'none',
                }}
              />
              <button
                onClick={addWF}
                style={{
                  padding: '9px 14px',
                  background: 'var(--admin)',
                  border: 'none',
                  borderRadius: 8,
                  color: '#0F0F0F',
                  fontSize: 13,
                }}
              >
                Add
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

// ─── MONTH SCREEN ─────────────────────────────────────────────────────────────
function MonthScreen({ who }) {
  const [monthTasks, setMonthTasks] = useState([]);
  const [completions, setCompletions] = useState(new Set());
  const [planItems, setPlanItems] = useState([]);
  const [loading, setLoading] = useState(true);
  const pKey = monthlyKey();

  const now = new Date();
  const currentMonthKey = `${String(now.getMonth() + 1).padStart(
    2,
    '0'
  )}/${now.getFullYear()}`;
  const monthName = now.toLocaleDateString('en-GB', {
    month: 'long',
    year: 'numeric',
  });

  useEffect(() => {
    const load = async () => {
      const [{ data: t }, { data: c }, { data: p }] = await Promise.all([
        sb
          .from('routine_tasks')
          .select('*')
          .eq('type', 'monthly')
          .order('sort_order'),
        sb.from('routine_completions').select('task_id').eq('period_key', pKey),
        sb
          .from('planning_events')
          .select('*')
          .eq('trigger_month', currentMonthKey)
          .eq('done', false)
          .eq('promoted', false),
      ]);
      setMonthTasks(t || []);
      setCompletions(new Set((c || []).map((r) => r.task_id)));
      // Merge DB plan items with local init for any not yet in DB
      setPlanItems(p || []);
      setLoading(false);
    };
    load();
    const sub = sb
      .channel('month_completions')
      .on(
        'postgres_changes',
        { event: '*', schema: 'public', table: 'routine_completions' },
        () => {
          sb.from('routine_completions')
            .select('task_id')
            .eq('period_key', pKey)
            .then(({ data }) => {
              setCompletions(new Set((data || []).map((r) => r.task_id)));
            });
        }
      )
      .on(
        'postgres_changes',
        { event: '*', schema: 'public', table: 'planning_events' },
        load
      )
      .subscribe();
    return () => sb.removeChannel(sub);
  }, [pKey, currentMonthKey]);

  const toggleRoutine = async (taskId) => {
    const done = completions.has(taskId);
    if (done) {
      await sb
        .from('routine_completions')
        .delete()
        .eq('task_id', taskId)
        .eq('period_key', pKey);
      setCompletions((s) => {
        const n = new Set(s);
        n.delete(taskId);
        return n;
      });
    } else {
      await sb
        .from('routine_completions')
        .upsert({ task_id: taskId, period_key: pKey, completed_by: who });
      setCompletions((s) => new Set([...s, taskId]));
    }
  };

  const tickPlanItem = async (item) => {
    await sb.from('planning_events').update({ done: true }).eq('id', item.id);
    setPlanItems((ps) => ps.filter((p) => p.id !== item.id));
  };

  const promotePlanItem = async (item) => {
    await sb
      .from('planning_events')
      .update({ promoted: true })
      .eq('id', item.id);
    const promotedItem = {
      id: `na_plan_${Date.now()}`,
      text: item.text,
      assigned: 'alba',
      context: 'phone',
      done: false,
    };
    const { error: promoteError } = await sb
      .from('next_actions')
      .insert(promotedItem);
    if (promoteError) console.error('promote error:', promoteError);
    setPlanItems((ps) => ps.filter((p) => p.id !== item.id));
  };

  const monthDone = monthTasks.filter((t) => completions.has(t.id)).length;

  // localThisMonth comes from Supabase via planItems state

  return (
    <div className="fade" style={{ padding: '0 0 100px' }}>
      <div style={{ padding: '32px 20px 18px' }}>
        <div
          style={{
            fontFamily: "'Cormorant Garamond', Georgia, serif",
            fontSize: 34,
            fontWeight: 300,
            color: 'var(--text)',
            marginBottom: 4,
            letterSpacing: '-0.3px',
          }}
        >
          This Month
        </div>
        <div
          style={{
            fontSize: 10,
            color: 'var(--muted)',
            fontFamily: "'DM Mono', monospace",
            letterSpacing: '1px',
            textTransform: 'uppercase',
          }}
        >
          {monthName} · resets 1st
        </div>
      </div>

      {/* Monthly recurring tasks */}
      {loading ? (
        <Spinner />
      ) : (
        <div style={{ padding: '0 20px 24px' }}>
          <SectionLabel
            text="Monthly Tasks"
            color="var(--planning)"
            done={monthDone}
            total={monthTasks.length}
          />
          <div
            style={{
              display: 'flex',
              flexDirection: 'column',
              gap: 2,
              marginTop: 12,
            }}
          >
            {monthTasks.map((t) => (
              <TaskRow
                key={t.id}
                text={t.text}
                done={completions.has(t.id)}
                onToggle={() => toggleRoutine(t.id)}
                color="var(--planning)"
              />
            ))}
          </div>
        </div>
      )}

      {/* Plan items surfaced this month */}
      {!loading && planItems.length > 0 && (
        <div style={{ padding: '0 20px' }}>
          <div
            style={{
              fontSize: 10,
              fontFamily: "'DM Mono', monospace",
              color: 'var(--planning)',
              textTransform: 'uppercase',
              letterSpacing: '1px',
              marginBottom: 10,
            }}
          >
            From Plan
          </div>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
            {planItems.map((e) => (
              <div
                key={e.id}
                style={{
                  padding: '12px 14px',
                  borderRadius: 12,
                  background: 'var(--surface)',
                  border: '1px solid var(--planning)44',
                }}
              >
                <div
                  style={{
                    display: 'flex',
                    alignItems: 'flex-start',
                    justifyContent: 'space-between',
                    gap: 8,
                  }}
                >
                  <div style={{ flex: 1 }}>
                    <div
                      style={{
                        fontSize: 14,
                        color: 'var(--text)',
                        marginBottom: e.notes ? 4 : 0,
                      }}
                    >
                      {e.text}
                    </div>
                    {e.notes && (
                      <div
                        style={{
                          fontSize: 11,
                          color: 'var(--muted)',
                          lineHeight: 1.5,
                        }}
                      >
                        {e.notes}
                      </div>
                    )}
                  </div>
                  <div
                    style={{
                      display: 'flex',
                      flexDirection: 'column',
                      gap: 5,
                      flexShrink: 0,
                    }}
                  >
                    <button
                      onClick={() => tickPlanItem(e)}
                      style={{
                        padding: '5px 10px',
                        borderRadius: 7,
                        background: 'var(--planning)22',
                        border: `1px solid var(--planning)44`,
                        color: 'var(--planning)',
                        fontSize: 11,
                        fontFamily: "'DM Mono', monospace",
                      }}
                    >
                      ✓ Done
                    </button>
                    <button
                      onClick={() => promotePlanItem(e)}
                      style={{
                        padding: '5px 10px',
                        borderRadius: 7,
                        background: 'var(--admin)22',
                        border: `1px solid var(--admin)44`,
                        color: 'var(--admin)',
                        fontSize: 11,
                        fontFamily: "'DM Mono', monospace",
                      }}
                    >
                      → Tasks
                    </button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {!loading && planItems.length === 0 && (
        <div style={{ padding: '0 20px' }}>
          <div
            style={{
              padding: '14px',
              borderRadius: 12,
              background: 'var(--surface)',
              border: '1px solid var(--border)',
              fontSize: 13,
              color: 'var(--muted)',
              textAlign: 'center',
            }}
          >
            Nothing from Plan this month
          </div>
        </div>
      )}
    </div>
  );
}

// ─── PLAN SCREEN ──────────────────────────────────────────────────────────────
function PlanScreen() {
  const [events, setEvents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [selectedMonth, setSelectedMonth] = useState(null);
  const now = new Date();
  const currentMonthKey = `${String(now.getMonth() + 1).padStart(
    2,
    '0'
  )}/${now.getFullYear()}`;

  useEffect(() => {
    const load = async () => {
      const { data, error } = await sb
        .from('planning_events')
        .select('*')
        .eq('done', false)
        .order('trigger_month');
      if (error) console.error('PlanScreen load error:', error);
      setEvents(data || []);
      setLoading(false);
    };
    load();
    const sub = sb
      .channel('plan_screen_rt')
      .on(
        'postgres_changes',
        { event: '*', schema: 'public', table: 'planning_events' },
        load
      )
      .subscribe();
    return () => sb.removeChannel(sub);
  }, []);

  // Build a 2-year calendar grid (this year + next)
  const years = [now.getFullYear(), now.getFullYear() + 1];
  const months = [
    'Jan',
    'Feb',
    'Mar',
    'Apr',
    'May',
    'Jun',
    'Jul',
    'Aug',
    'Sep',
    'Oct',
    'Nov',
    'Dec',
  ];

  const eventsForMonth = (m, y) => {
    const key = `${String(m + 1).padStart(2, '0')}/${y}`;
    return events.filter((e) => e.trigger_month === key);
  };

  const monthKey = (m, y) => `${String(m + 1).padStart(2, '0')}/${y}`;
  const selectedEvents = selectedMonth
    ? events.filter((e) => e.trigger_month === selectedMonth)
    : [];

  return (
    <div className="fade" style={{ padding: '0 0 100px' }}>
      <div style={{ padding: '32px 20px 18px' }}>
        <div
          style={{
            fontFamily: "'Cormorant Garamond', Georgia, serif",
            fontSize: 34,
            fontWeight: 300,
            color: 'var(--text)',
            marginBottom: 4,
            letterSpacing: '-0.3px',
          }}
        >
          Plan
        </div>
        <div
          style={{
            fontSize: 10,
            color: 'var(--muted)',
            fontFamily: "'DM Mono', monospace",
            letterSpacing: '1px',
            textTransform: 'uppercase',
          }}
        >
          Tap a month to see events
        </div>
      </div>

      {loading ? (
        <Spinner />
      ) : (
        <div style={{ padding: '0 20px' }}>
          {years.map((year) => (
            <div key={year} style={{ marginBottom: 36 }}>
              <div
                style={{
                  fontSize: 10,
                  fontFamily: "'DM Mono', monospace",
                  color: 'var(--planning)',
                  textTransform: 'uppercase',
                  letterSpacing: '1.2px',
                  marginBottom: 12,
                }}
              >
                {year}
              </div>
              <div
                style={{
                  display: 'grid',
                  gridTemplateColumns: 'repeat(4, 1fr)',
                  gap: 10,
                }}
              >
                {months.map((mon, mi) => {
                  const key = monthKey(mi, year);
                  const evts = eventsForMonth(mi, year);
                  const isCurrentMonth = key === currentMonthKey;
                  const isSelected = key === selectedMonth;
                  const isPast =
                    new Date(year, mi) <
                    new Date(now.getFullYear(), now.getMonth());
                  return (
                    <button
                      key={mon}
                      onClick={() => setSelectedMonth(isSelected ? null : key)}
                      style={{
                        padding: '12px 10px',
