// ─── INBOX SCREEN ─────────────────────────────────────────────────────────────
function InboxScreen({ who }) {
  const [emails, setEmails] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [creating, setCreating] = useState(null); // { email, type: 'task'|'plan' }
  const [newText, setNewText] = useState('');
  const [newContext, setNewContext] = useState('phone');
  const [newTrigger, setNewTrigger] = useState('');
  const [success, setSuccess] = useState(null);

  useEffect(() => {
    const fetchEmails = async () => {
      setLoading(true);
      try {
        const response = await fetch('https://api.anthropic.com/v1/messages', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            model: 'claude-sonnet-4-20250514',
            max_tokens: 1000,
            system:
              "You are a helpful assistant. Use the Gmail MCP tool to find emails that need a reply — specifically emails where the most recent message in the thread was sent by someone else (not the user), meaning the user hasn't replied yet. Return ONLY a JSON array of up to 10 objects with fields: id (string), from (string), subject (string), preview (string, max 100 chars), date (string). No markdown, no explanation.",
            messages: [
              {
                role: 'user',
                content: 'Find my emails that need a reply. Return JSON only.',
              },
            ],
            mcp_servers: [
              {
                type: 'url',
                url: 'https://gmailmcp.googleapis.com/mcp/v1',
                name: 'gmail-mcp',
              },
            ],
          }),
        });
        const data = await response.json();
        const text =
          data.content
            ?.filter((b) => b.type === 'text')
            .map((b) => b.text)
            .join('') || '[]';
        const clean = text.replace(/```json|```/g, '').trim();
        const parsed = JSON.parse(clean.startsWith('[') ? clean : '[]');
        setEmails(parsed);
      } catch (e) {
        setError("Couldn't load emails. Check Gmail is connected.");
        console.error(e);
      }
      setLoading(false);
    };
    fetchEmails();
  }, []);

  const createTask = async () => {
    if (!newText.trim()) return;
    const newItem = {
      id: `na_inbox_${Date.now()}`,
      text: newText.trim(),
      assigned: 'alba',
      context: newContext,
      done: false,
    };
    await sb.from('next_actions').insert(newItem);
    setSuccess(`Added to Tasks: "${newText}"`);
    setCreating(null);
    setNewText('');
    setNewContext('phone');
    setTimeout(() => setSuccess(null), 3000);
  };

  const createPlan = async () => {
    if (!newText.trim()) return;
    const newEvent = {
      id: `pl_inbox_${Date.now()}`,
      text: newText.trim(),
      date: '',
      trigger_month: newTrigger,
      notes: creating?.email?.subject || '',
      recurring: false,
      done: false,
      promoted: false,
    };
    await sb.from('planning_events').insert(newEvent);
    setSuccess(`Added to Plan: "${newText}"`);
    setCreating(null);
    setNewText('');
    setNewTrigger('');
    setTimeout(() => setSuccess(null), 3000);
  };

  return (
    <div className="fade" style={{ padding: '0 0 100px' }}>
      <div style={{ padding: '32px 20px 18px' }}>
        <div
          style={{
            fontFamily: "'Cormorant Garamond', Georgia, serif",
            fontSize: 34,
            fontWeight: 300,
            color: 'var(--text)',
            marginBottom: 4,
            letterSpacing: '-0.3px',
          }}
        >
          Inbox
        </div>
        <div
          style={{
            fontSize: 10,
            color: 'var(--muted)',
            fontFamily: "'DM Mono', monospace",
            letterSpacing: '1px',
            textTransform: 'uppercase',
          }}
        >
          Emails needing a reply
        </div>
      </div>

      {success && (
        <div
          style={{
            margin: '0 20px 12px',
            padding: '10px 14px',
            background: 'var(--chores)15',
            border: `1px solid var(--chores)44`,
            borderRadius: 10,
            fontSize: 13,
            color: 'var(--chores)',
          }}
