          style={{
            margin: '0 20px',
            padding: '16px',
            borderRadius: 12,
            background: 'var(--surface)',
            border: '1px solid var(--border)',
          }}
        >
          <div
            style={{
              fontSize: 13,
              color: 'var(--text)',
              fontWeight: 500,
              marginBottom: 6,
            }}
          >
            Gmail not reachable
          </div>
          <div style={{ fontSize: 12, color: 'var(--muted)', lineHeight: 1.6 }}>
            Gmail integration requires the app to be deployed — it can't connect
            from Stackblitz due to browser security restrictions. Once you
