// ─── EDIT SCREEN ──────────────────────────────────────────────────────────────
function EditSection({
  title,
  color,
  items,
  onAdd,
  onRemove,
  onEdit,
  placeholder,
  extraFields,
}) {
  const [adding, setAdding] = useState(false);
  const [text, setText] = useState('');
  const [extra, setExtra] = useState({});
  const [editingIdx, setEditingIdx] = useState(null);
  const [editText, setEditText] = useState('');
  const [editExtra, setEditExtra] = useState({});

  const submit = () => {
    if (!text.trim()) return;
    onAdd(text.trim(), extra);
    setText('');
    setExtra({});
    setAdding(false);
  };

  const startEdit = (i) => {
    const item = items[i];
    setEditingIdx(i);
    setEditText(typeof item === 'string' ? item : item.text || '');
    setEditExtra(
      typeof item === 'object'
        ? { notes: item.notes || '', trigger_month: item.trigger_month || '' }
        : {}
    );
  };

  const submitEdit = () => {
    if (!editText.trim()) return;
    onEdit(editingIdx, editText.trim(), editExtra);
    setEditingIdx(null);
  };

  const getLabel = (item) =>
    typeof item === 'string' ? item : item.text || item.label || '';
  const getSub = (item) => {
    if (typeof item !== 'object') return null;
    const parts = [];
    if (item.trigger_month) parts.push(item.trigger_month);
    if (item.notes) parts.push(item.notes);
    return parts.length ? parts.join(' · ') : null;
  };

  return (
    <div style={{ marginBottom: 28 }}>
      <div
        style={{
          fontSize: 10,
          fontFamily: "'DM Mono', monospace",
          color,
          textTransform: 'uppercase',
          letterSpacing: '1px',
          marginBottom: 10,
        }}
      >
        {title}
      </div>
      <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
        {items.map((item, i) =>
          editingIdx === i ? (
            <div
              key={i}
              style={{
                display: 'flex',
                flexDirection: 'column',
                gap: 6,
                background: 'var(--surface2)',
                borderRadius: 10,
                padding: 12,
                border: `1px solid ${color}44`,
              }}
            >
              <input
                autoFocus
                value={editText}
                onChange={(e) => setEditText(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === 'Enter') submitEdit();
                  if (e.key === 'Escape') setEditingIdx(null);
                }}
                style={{
                  background: 'var(--surface)',
                  border: '1px solid var(--border)',
                  borderRadius: 8,
                  padding: '8px 11px',
                  color: 'var(--text)',
                  fontSize: 13,
                  outline: 'none',
                }}
              />
              {extraFields &&
                extraFields.map((f) =>
                  f.type === 'checkbox' ? (
                    <div
                      key={f.key}
                      style={{
                        display: 'flex',
                        alignItems: 'center',
                        gap: 10,
                        padding: '8px 11px',
                        background: 'var(--surface)',
                        borderRadius: 8,
                        border: '1px solid var(--border)',
                      }}
                    >
                      <div
                        onClick={() =>
                          setEditExtra((x) => ({ ...x, [f.key]: !x[f.key] }))
                        }
                        style={{
                          width: 20,
                          height: 20,
                          borderRadius: 6,
                          border: `2px solid ${
                            editExtra[f.key] ? color : '#444'
                          }`,
                          background: editExtra[f.key] ? color : 'transparent',
                          display: 'flex',
                          alignItems: 'center',
                          justifyContent: 'center',
                          cursor: 'pointer',
                          flexShrink: 0,
                        }}
                      >
                        {editExtra[f.key] && (
                          <svg width="11" height="11" viewBox="0 0 12 12">
                            <polyline
                              points="2,6 5,9 10,3"
                              fill="none"
                              stroke="#0F0F0F"
                              strokeWidth="2.2"
                              strokeLinecap="round"
                              strokeLinejoin="round"
                            />
                          </svg>
                        )}
                      </div>
                      <span
                        style={{
                          fontSize: 13,
                          color: 'var(--text)',
                          cursor: 'pointer',
                        }}
                        onClick={() =>
                          setEditExtra((x) => ({ ...x, [f.key]: !x[f.key] }))
                        }
                      >
                        {f.placeholder}
                      </span>
                    </div>
                  ) : (
                    <input
                      key={f.key}
                      value={editExtra[f.key] || ''}
                      onChange={(e) =>
                        setEditExtra((x) => ({ ...x, [f.key]: e.target.value }))
                      }
                      placeholder={f.placeholder}
                      style={{
                        background: 'var(--surface)',
                        border: '1px solid var(--border)',
                        borderRadius: 8,
                        padding: '8px 11px',
                        color: 'var(--text)',
                        fontSize: 13,
                        outline: 'none',
                      }}
                    />
                  )
                )}
              <div style={{ display: 'flex', gap: 6 }}>
                <button
                  onClick={submitEdit}
                  style={{
                    flex: 1,
                    padding: '7px',
                    background: color,
                    border: 'none',
                    borderRadius: 8,
                    color: '#0F0F0F',
                    fontSize: 12,
                    fontWeight: 500,
                  }}
                >
                  Save
                </button>
                <button
                  onClick={() => setEditingIdx(null)}
                  style={{
                    padding: '7px 12px',
                    background: 'var(--surface)',
                    border: 'none',
                    borderRadius: 8,
                    color: 'var(--muted)',
                    fontSize: 12,
                  }}
                >
                  Cancel
                </button>
              </div>
            </div>
          ) : (
            <div
              key={i}
              style={{
                display: 'flex',
                alignItems: 'center',
                gap: 10,
                padding: '9px 12px',
                background: 'var(--surface)',
                borderRadius: 10,
                border: '1px solid var(--border)',
              }}
            >
              <div style={{ flex: 1 }} onClick={() => startEdit(i)}>
                <div style={{ fontSize: 13, color: 'var(--text)' }}>
                  {getLabel(item)}
                </div>
                {getSub(item) && (
                  <div
                    style={{
                      fontSize: 10,
                      color: 'var(--muted)',
                      fontFamily: "'DM Mono', monospace",
                      marginTop: 2,
                    }}
                  >
                    {getSub(item)}
                  </div>
                )}
              </div>
              <button
                onClick={() => startEdit(i)}
                style={{
                  background: 'none',
                  border: 'none',
                  color: 'var(--muted)',
                  fontSize: 12,
                  padding: '0 4px',
                }}
              >
                ✎
              </button>
              <button
                onClick={() => onRemove(i)}
                style={{
                  background: 'none',
                  border: 'none',
                  color: 'var(--muted)',
                  fontSize: 16,
                  padding: '0 2px',
                  lineHeight: 1,
                }}
              >
                ×
              </button>
            </div>
          )
        )}
        {!adding ? (
          <button
            onClick={() => setAdding(true)}
            style={{
              padding: '8px',
              background: 'none',
              border: `1.5px dashed ${color}66`,
              borderRadius: 10,
              color,
              fontSize: 12,
            }}
          >
            + Add
          </button>
        ) : (
          <div
            style={{
              display: 'flex',
              flexDirection: 'column',
              gap: 6,
              background: 'var(--surface)',
              borderRadius: 10,
              padding: 12,
              border: '1px solid var(--border)',
            }}
          >
            <input
              autoFocus
              value={text}
              onChange={(e) => setText(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === 'Enter') submit();
                if (e.key === 'Escape') setAdding(false);
              }}
              placeholder={placeholder || 'Add item…'}
              style={{
                background: 'var(--surface2)',
                border: '1px solid var(--border)',
                borderRadius: 8,
                padding: '8px 11px',
                color: 'var(--text)',
                fontSize: 13,
                outline: 'none',
              }}
            />
            {extraFields &&
              extraFields.map((f) =>
                f.type === 'checkbox' ? (
                  <div
                    key={f.key}
                    style={{
                      display: 'flex',
                      alignItems: 'center',
                      gap: 10,
                      padding: '8px 11px',
                      background: 'var(--surface2)',
                      borderRadius: 8,
                      border: '1px solid var(--border)',
                    }}
                  >
                    <div
                      onClick={() =>
                        setExtra((x) => ({ ...x, [f.key]: !x[f.key] }))
                      }
                      style={{
                        width: 20,
                        height: 20,
                        borderRadius: 6,
                        border: `2px solid ${extra[f.key] ? color : '#444'}`,
                        background: extra[f.key] ? color : 'transparent',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        cursor: 'pointer',
                        flexShrink: 0,
                      }}
                    >
                      {extra[f.key] && (
                        <svg width="11" height="11" viewBox="0 0 12 12">
                          <polyline
                            points="2,6 5,9 10,3"
                            fill="none"
                            stroke="#0F0F0F"
                            strokeWidth="2.2"
                            strokeLinecap="round"
                            strokeLinejoin="round"
                          />
                        </svg>
                      )}
                    </div>
                    <span
                      style={{
                        fontSize: 13,
                        color: 'var(--text)',
                        cursor: 'pointer',
                      }}
                      onClick={() =>
                        setExtra((x) => ({ ...x, [f.key]: !x[f.key] }))
                      }
                    >
                      {f.placeholder}
                    </span>
                  </div>
                ) : (
                  <input
                    key={f.key}
                    value={extra[f.key] || ''}
                    onChange={(e) =>
                      setExtra((x) => ({ ...x, [f.key]: e.target.value }))
                    }
                    placeholder={f.placeholder}
                    style={{
                      background: 'var(--surface2)',
                      border: '1px solid var(--border)',
                      borderRadius: 8,
                      padding: '8px 11px',
                      color: 'var(--text)',
                      fontSize: 13,
                      outline: 'none',
                    }}
                  />
                )
              )}
            <div style={{ display: 'flex', gap: 6 }}>
              <button
                onClick={submit}
                style={{
                  flex: 1,
                  padding: '8px',
                  background: color,
                  border: 'none',
                  borderRadius: 8,
                  color: '#0F0F0F',
                  fontSize: 12,
                  fontWeight: 500,
                }}
              >
                Add
              </button>
              <button
                onClick={() => {
                  setAdding(false);
                  setText('');
                  setExtra({});
                }}
                style={{
                  padding: '8px 12px',
                  background: 'var(--surface2)',
                  border: 'none',
                  borderRadius: 8,
                  color: 'var(--muted)',
                  fontSize: 12,
                }}
              >
                Cancel
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

function EditScreen({ onBack }) {
  const [morningTasks, setMorningTasks] = useState([]);
  const [eveningTasks, setEveningTasks] = useState([]);
  const [weeklyOther, setWeeklyOther] = useState([]);
  const [monthlyTasks, setMonthlyTasks] = useState([]);
  const [rooms, setRooms] = useState([]);
  const [planEvents, setPlanEvents] = useState([]);
  const [agenda, setAgenda] = useState([...JOSH_AGENDA]);
  const [loading, setLoading] = useState(true);
  const [activeSection, setActiveSection] = useState(null);

  useEffect(() => {
    const load = async () => {
      const [{ data }, { data: planData }, { data: agendaData }] =
        await Promise.all([
          sb.from('routine_tasks').select('*').order('sort_order'),
          sb.from('planning_events').select('*').order('trigger_month'),
          sb.from('josh_agenda').select('*').order('sort_order'),
        ]);
      if (planData) setPlanEvents(planData);
      if (agendaData) setAgenda(agendaData.map((a) => a.text));
      if (data) {
        setMorningTasks(data.filter((t) => t.type === 'morning'));
        setEveningTasks(data.filter((t) => t.type === 'evening'));
        setWeeklyOther(data.filter((t) => t.type === 'weekly_other'));
        setMonthlyTasks(data.filter((t) => t.type === 'monthly'));
        // Group room tasks by room
        const roomTasks = data.filter((t) => t.type === 'weekly_room');
        const grouped = ROOMS.map((r) => ({
          ...r,
          tasks: roomTasks
            .filter((t) => t.id.startsWith(`wr_${r.id}_`))
            .map((t) => t.text),
        }));
        setRooms(grouped);
      }
      setLoading(false);
    };
    load();
  }, []);

  const addRoutineTask = async (type, text, sortOrder) => {
    const id = `${type}_custom_${Date.now()}`;
    const newItem = { id, text, type, sort_order: sortOrder, sub_items: null };
    const { data, error } = await sb
      .from('routine_tasks')
      .insert(newItem)
      .select('id, text, type, sort_order, sub_items')
      .single();
    if (error) console.error('addRoutineTask error:', error);
    return data || newItem;
  };

  const removeRoutineTask = async (id) => {
    await sb.from('routine_tasks').delete().eq('id', id);
  };

  const sections = [
    { key: 'morning', label: 'Morning Routine', color: 'var(--morning)' },
    { key: 'evening', label: 'After Dinner', color: 'var(--evening)' },
    { key: 'weekly_other', label: 'Weekly Admin', color: 'var(--admin)' },
    { key: 'monthly', label: 'Monthly Tasks', color: 'var(--planning)' },
    { key: 'rooms', label: 'Weekly Rooms', color: 'var(--chores)' },
    { key: 'plan', label: 'Plan Events', color: 'var(--planning)' },
    { key: 'agenda', label: 'Josh Meeting Agenda', color: 'var(--josh)' },
  ];

  const getItems = (key) => {
    if (key === 'morning') return morningTasks;
    if (key === 'evening') return eveningTasks;
    if (key === 'weekly_other') return weeklyOther;
    if (key === 'monthly') return monthlyTasks;
    if (key === 'rooms') return rooms;
    if (key === 'plan') return planEvents;
    if (key === 'agenda') return agenda.map((a) => ({ text: a }));
    return [];
  };

  const handleAdd = async (key, text, extra) => {
    if (key === 'morning') {
      const data = await addRoutineTask(
        'morning',
        text,
        morningTasks.length + 1
      );
      if (data) setMorningTasks((ts) => [...ts, data]);
    } else if (key === 'evening') {
      const data = await addRoutineTask(
        'evening',
        text,
        eveningTasks.length + 1
      );
      if (data) setEveningTasks((ts) => [...ts, data]);
    } else if (key === 'weekly_other') {
      const data = await addRoutineTask(
        'weekly_other',
        text,
        weeklyOther.length + 1
      );
      if (data) setWeeklyOther((ts) => [...ts, data]);
    } else if (key === 'monthly') {
      const data = await addRoutineTask(
        'monthly',
        text,
        monthlyTasks.length + 1
      );
      if (data) setMonthlyTasks((ts) => [...ts, data]);
    } else if (key === 'plan') {
      const newEvent = {
        id: `custom_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`,
        text,
        date: '',
        trigger_month: extra.trigger_month || '',
        notes: extra.notes || '',
        recurring: extra.recurring === true,
        done: false,
        promoted: false,
      };
      console.log('Inserting plan event:', newEvent);
      const { data: planData, error } = await sb
        .from('planning_events')
        .insert(newEvent)
        .select('id, text, trigger_month, notes, recurring, done, promoted')
        .single();
      console.log('Plan insert result - data:', planData, 'error:', error);
      if (error) {
        alert(
          'Save failed: ' +
            error.message +
            '\nDetails: ' +
            JSON.stringify(error.details)
        );
      } else if (planData) {
        setPlanEvents((es) => [...es, planData]);
      } else {
        alert('Insert returned no data - check Supabase logs');
      }
    } else if (key === 'agenda') {
      const { data, error } = await sb
        .from('josh_agenda')
        .insert({ text, sort_order: agenda.length + 1 })
        .select('id, text, sort_order')
        .single();
      if (error) console.error('agenda add error:', error);
      setAgenda((ag) => [...ag, (data || { text }).text]);
    }
  };

  const handleRemove = async (key, idx) => {
    if (key === 'morning') {
      await removeRoutineTask(morningTasks[idx].id);
      setMorningTasks((ts) => ts.filter((_, i) => i !== idx));
    } else if (key === 'evening') {
      await removeRoutineTask(eveningTasks[idx].id);
      setEveningTasks((ts) => ts.filter((_, i) => i !== idx));
    } else if (key === 'weekly_other') {
      await removeRoutineTask(weeklyOther[idx].id);
      setWeeklyOther((ts) => ts.filter((_, i) => i !== idx));
    } else if (key === 'monthly') {
      await removeRoutineTask(monthlyTasks[idx].id);
      setMonthlyTasks((ts) => ts.filter((_, i) => i !== idx));
    } else if (key === 'plan') {
      const item = planEvents[idx];
      if (item?.id) await sb.from('planning_events').delete().eq('id', item.id);
      setPlanEvents((es) => es.filter((_, i) => i !== idx));
    } else if (key === 'agenda') {
      const text = agenda[idx];
      await sb.from('josh_agenda').delete().eq('text', text);
      setAgenda((ag) => ag.filter((_, i) => i !== idx));
    }
  };

  const handleEdit = async (key, idx, text, extra) => {
    const update = (setter, arr) =>
      setter(
        arr.map((item, i) =>
          i === idx
            ? typeof item === 'string'
              ? text
              : { ...item, text, ...extra }
            : item
        )
      );
    if (key === 'morning') {
      await sb
        .from('routine_tasks')
        .update({ text })
        .eq('id', morningTasks[idx].id);
      update(setMorningTasks, morningTasks);
    } else if (key === 'evening') {
      await sb
        .from('routine_tasks')
        .update({ text })
        .eq('id', eveningTasks[idx].id);
      update(setEveningTasks, eveningTasks);
    } else if (key === 'weekly_other') {
      await sb
        .from('routine_tasks')
        .update({ text })
        .eq('id', weeklyOther[idx].id);
      update(setWeeklyOther, weeklyOther);
    } else if (key === 'monthly') {
      await sb
        .from('routine_tasks')
        .update({ text })
        .eq('id', monthlyTasks[idx].id);
      update(setMonthlyTasks, monthlyTasks);
    } else if (key === 'plan') {
      const item = planEvents[idx];
      if (item?.id) {
        await sb
          .from('planning_events')
          .update({
            text,
            trigger_month: extra.trigger_month || item.trigger_month,
            notes: extra.notes !== undefined ? extra.notes : item.notes,
            recurring:
              extra.recurring !== undefined ? extra.recurring : item.recurring,
          })
          .eq('id', item.id);
      }
      setPlanEvents((es) =>
        es.map((e, i) => (i === idx ? { ...e, text, ...extra } : e))
      );
    } else if (key === 'agenda') {
      const oldText = agenda[idx];
      await sb.from('josh_agenda').update({ text }).eq('text', oldText);
      setAgenda((ag) => ag.map((a, i) => (i === idx ? text : a)));
    }
  };

  return (
    <div className="fade" style={{ padding: '0 0 40px' }}>
      {/* Header */}
      <div
        style={{
          padding: '32px 20px 20px',
          display: 'flex',
          alignItems: 'center',
          gap: 14,
        }}
      >
        <button
          onClick={onBack}
          style={{
            background: 'var(--surface)',
            border: '1px solid var(--border)',
            borderRadius: 10,
            width: 36,
            height: 36,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            color: 'var(--muted)',
            fontSize: 16,
            boxShadow: '0 1px 4px #2C282510',
          }}
        >
          ←
        </button>
        <div>
          <div
            style={{
              fontFamily: "'Cormorant Garamond', Georgia, serif",
              fontSize: 30,
              fontWeight: 300,
              color: 'var(--text)',
              letterSpacing: '-0.3px',
            }}
          >
            Edit Lists
          </div>
          <div
            style={{
              fontSize: 10,
              color: 'var(--muted)',
              fontFamily: "'DM Mono', monospace",
              letterSpacing: '1px',
              textTransform: 'uppercase',
            }}
          >
            Tap a section to expand
          </div>
        </div>
      </div>

      {loading ? (
        <Spinner />
      ) : (
        <div style={{ padding: '0 20px' }}>
          {/* History section */}
          <div
            style={{
              marginBottom: 8,
              borderRadius: 12,
              overflow: 'hidden',
              border: '1px solid var(--border)',
              background: 'var(--surface)',
            }}
          >
            <button
              onClick={() =>
                setActiveSection(activeSection === 'history' ? null : 'history')
              }
              style={{
                width: '100%',
                padding: '14px 16px',
                background: 'none',
                border: 'none',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'space-between',
                color: 'var(--text)',
              }}
            >
              <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                <div
                  style={{
                    width: 8,
                    height: 8,
                    borderRadius: '50%',
                    background: 'var(--muted)',
                  }}
                />
                <span style={{ fontSize: 14 }}>History</span>
              </div>
              <span
                style={{
                  fontSize: 10,
                  color: 'var(--muted)',
                  transform:
                    activeSection === 'history' ? 'rotate(180deg)' : 'none',
                  transition: '0.2s',
                }}
              >
                ▾
              </span>
            </button>
            {activeSection === 'history' && (
              <div style={{ borderTop: '1px solid var(--border)' }}>
                <HistorySection />
              </div>
            )}
          </div>
          {sections.map((s) => (
            <div
              key={s.key}
              style={{
                marginBottom: 8,
                borderRadius: 12,
                overflow: 'hidden',
                border: '1px solid var(--border)',
                background: 'var(--surface)',
              }}
            >
              <button
                onClick={() =>
                  setActiveSection(activeSection === s.key ? null : s.key)
                }
                style={{
                  width: '100%',
                  padding: '14px 16px',
                  background: 'none',
                  border: 'none',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'space-between',
                  color: 'var(--text)',
                }}
              >
                <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                  <div
                    style={{
                      width: 8,
                      height: 8,
                      borderRadius: '50%',
                      background: s.color,
                    }}
                  />
                  <span style={{ fontSize: 14 }}>{s.label}</span>
                  <span
                    style={{
                      fontSize: 10,
                      fontFamily: "'DM Mono', monospace",
                      color: 'var(--muted)',
                    }}
                  >
                    {getItems(s.key).length}
                  </span>
                </div>
                <span
                  style={{
                    fontSize: 10,
                    color: 'var(--muted)',
                    transform:
                      activeSection === s.key ? 'rotate(180deg)' : 'none',
                    transition: '0.2s',
                  }}
                >
                  ▾
                </span>
              </button>
              {activeSection === s.key && (
                <div
                  style={{
                    borderTop: '1px solid var(--border)',
                    padding: '12px 16px',
                  }}
                >
                  <EditSection
                    title=""
                    color={s.color}
                    items={getItems(s.key)}
                    onAdd={(text, extra) => handleAdd(s.key, text, extra)}
                    onRemove={(idx) => handleRemove(s.key, idx)}
                    onEdit={(idx, text, extra) =>
                      handleEdit(s.key, idx, text, extra)
                    }
                    placeholder={
                      s.key === 'plan' ? 'Event name…' : 'Task name…'
                    }
                    extraFields={
                      s.key === 'plan'
                        ? [
                            {
                              key: 'trigger_month',
                              placeholder: 'Trigger month (MM/YYYY)',
                            },
                            { key: 'notes', placeholder: 'Notes (optional)' },
                            {
                              key: 'recurring',
                              placeholder: 'Recurring annually',
                              type: 'checkbox',
                            },
                          ]
                        : null
                    }
                  />
                </div>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

// ─── BOTTOM NAV ───────────────────────────────────────────────────────────────
const NAV = [
  { key: 'today', label: 'Today', icon: '◎' },
  { key: 'week', label: 'Week', icon: '▦' },
  { key: 'month', label: 'Month', icon: '◫' },
  { key: 'tasks', label: 'Tasks', icon: '◈' },
  { key: 'plan', label: 'Plan', icon: '◷' },
  { key: 'inbox', label: 'Inbox', icon: '◻' },
];

function BottomNav({ active, onChange, who, onWhoReset }) {
  return (
    <div
      style={{
        position: 'fixed',
        bottom: 0,
        left: 0,
        right: 0,
        maxWidth: 480,
        margin: '0 auto',
        background: 'rgba(250,248,245,0.94)',
        backdropFilter: 'blur(24px)',
        borderTop: '1px solid var(--border)',
        display: 'flex',
        padding: '10px 0 env(safe-area-inset-bottom, 20px)',
        zIndex: 100,
        boxShadow: '0 -4px 24px #2C282508',
      }}
    >
      {NAV.map((n) => (
        <button
          key={n.key}
          onClick={() => onChange(n.key)}
          style={{
            flex: 1,
            background: 'none',
            border: 'none',
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            gap: 4,
            padding: '4px 0',
            color: active === n.key ? 'var(--text)' : 'var(--muted2)',
            transition: 'color 0.18s',
          }}
        >
          <span style={{ fontSize: 16, lineHeight: 1 }}>{n.icon}</span>
          <span
            style={{
              fontSize: 9,
              fontFamily: "'DM Mono', monospace",
              letterSpacing: '0.8px',
              textTransform: 'uppercase',
            }}
          >
            {n.label}
          </span>
          {active === n.key && (
            <div
              style={{
                width: 16,
                height: 2,
                borderRadius: 1,
                background: 'var(--text)',
                marginTop: 1,
              }}
            />
          )}
        </button>
      ))}
    </div>
  );
}

// ─── APP ──────────────────────────────────────────────────────────────────────
function SettingsIcon({ onPress }) {
  return (
    <button
      onClick={onPress}
      style={{
        position: 'fixed',
        top: 22,
        right: 20,
        zIndex: 200,
        background: 'var(--surface)',
        border: '1px solid var(--border)',
        borderRadius: 10,
        width: 34,
        height: 34,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        color: 'var(--muted)',
        fontSize: 14,
        boxShadow: '0 1px 4px #2C282510',
      }}
    >
      ⚙
    </button>
  );
}

export default function App() {
  const [who, chooseWho] = useWho();
  const [screen, setScreen] = useState('today');
  const [editing, setEditing] = useState(false);

  if (!who)
    return (
      <>
        <GlobalStyles />
        <WhoScreen onChoose={chooseWho} />
      </>
    );
  if (editing)
    return (
      <div
        style={{
          minHeight: '100vh',
          background: 'var(--bg)',
          maxWidth: 480,
          margin: '0 auto',
        }}
      >
        <GlobalStyles />
        <EditScreen onBack={() => setEditing(false)} />
      </div>
    );

  const screens = {
    today: <TodayScreen who={who} />,
    week: <WeekScreen who={who} />,
    month: <MonthScreen who={who} />,
    tasks: <TasksScreen who={who} />,
    plan: <PlanScreen />,
    inbox: <InboxScreen who={who} />,
  };

  return (
    <div
      style={{
        minHeight: '100vh',
        background: 'var(--bg)',
        maxWidth: 480,
        margin: '0 auto',
        position: 'relative',
      }}
    >
      <GlobalStyles />
      <SettingsIcon onPress={() => setEditing(true)} />
      <div key={screen} className="fade">
        {screens[screen]}
      </div>
      <BottomNav active={screen} onChange={setScreen} who={who} />
    </div>
  );
}
